import {Chess} from './chess.js';
import {mountExplorer} from './explorer.js';
import {lessons,puzzles} from './curriculum.js';
const $=id=>document.getElementById(id), names={p:'pawn',n:'knight',b:'bishop',r:'rook',q:'queen',k:'king'},symbols={p:'♟',n:'♞',b:'♝',r:'♜',q:'♛',k:'♚'},values={p:100,n:320,b:330,r:500,q:900,k:0};
let showThreats=true, hinted=null, reviewText='', completed=new Set(), practiceSnapshot=null;
let game=new Chess(),mode='play',selected=null,pending=null,last=null,timer=null,busy=false,lesson=0,puzzle=0,solved=false;
let hintLevel=0,puzzleStage=0,puzzlesCompleted=new Set(),guided=true;
try{let saved=JSON.parse(localStorage.getItem('bloom-learning-v1')||'{}');completed=new Set((saved.lessons||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<lessons.length));puzzlesCompleted=new Set((saved.puzzles||[]).filter(i=>Number.isInteger(i)&&i>=0&&i<puzzles.length));}catch{}
function saveProgress(){try{localStorage.setItem('bloom-learning-v1',JSON.stringify({lessons:[...completed],puzzles:[...puzzlesCompleted]}));}catch{}}
function progress(){ $('progress-count').textContent=completed.size+' / '+lessons.length+' lessons · '+puzzlesCompleted.size+' / '+puzzles.length+' puzzles';$('progress-bar').value=completed.size+puzzlesCompleted.size;$('progress-bar').max=lessons.length+puzzles.length;}
$('move-dock').append($('preview'));
function coach(title,copy){$('coach-title').textContent=title;$('coach-copy').textContent=copy;}
function evaluate(g){if(g.isCheckmate())return g.turn()==='w'?-100000:100000; if(g.isDraw())return 0;let score=0;for(let row of g.board())for(let p of row)if(p){let f=p.square.charCodeAt(0)-97,r=+p.square[1];let center=(3.5-Math.abs(3.5-f))+(3.5-Math.abs(4.5-r));let bonus=p.type==='p'?(p.color==='w'?r-2:7-r)*8+center*4:['n','b'].includes(p.type)?center*12:0;score+=(p.color==='w'?1:-1)*(values[p.type]+bonus);}return score;}
function search(g,depth,alpha=-Infinity,beta=Infinity){if(!depth||g.isGameOver())return evaluate(g);let white=g.turn()==='w',best=white?-Infinity:Infinity;let moves=g.moves({verbose:true}).sort((a,b)=>(values[b.captured]||0)-(values[a.captured]||0));for(let m of moves){g.move(m);let score=search(g,depth-1,alpha,beta);g.undo();best=white?Math.max(best,score):Math.min(best,score);if(white)alpha=Math.max(alpha,best);else beta=Math.min(beta,best);if(beta<=alpha)break;}return best;}
function bestMove(g){let white=g.turn()==='w',best=white?-Infinity:Infinity,choice=null;for(let m of g.moves({verbose:true})){g.move(m);let score=search(g,1);g.undo();if((white&&score>best)||(!white&&score<best)){best=score;choice=m;}}return choice;}
function explain(m){let text=`Your ${names[m.piece]} moves from ${m.from} to ${m.to}. `;if(m.captured)text+=`It captures a ${names[m.captured]}. `;if(m.promotion)text+=`Your pawn becomes a ${names[m.promotion]}. `;if(m.flags.includes('k')||m.flags.includes('q'))text+='Castling tucks your king away and brings your rook closer to the action. ';else if(m.piece==='p'&&['d4','e4'].includes(m.to))text+='A center pawn controls useful squares and opens paths for your pieces. ';else if(['n','b'].includes(m.piece)&&['1','8'].includes(m.from[1]))text+='Developing a piece brings another helper into the game. ';let test=new Chess(game.fen());test.move(m);if(test.isCheckmate())text+='Checkmate! The king has no legal escape.';else if(test.isCheck())text+='This gives check: the opponent must protect their king. ';let exposed=test.board().flat().filter(p=>p&&p.color==='w'&&p.type!=='k'&&test.isAttacked(p.square,'b')&&!test.isAttacked(p.square,'w'));if(exposed.length)text+=`Unprotected and attacked: ${exposed.map(p=>names[p.type]+' on '+p.square).join(', ')}. `;if(test.isAttacked(m.to,'b')&&!test.isCheckmate())text+='Watch out: Black attacks this destination. Consider whether the piece is protected or the trade is worth it.';return text;}
function replyPreview(m){let copy=new Chess(game.fen());copy.move(m);if(copy.isGameOver())return '';let reply=bestMove(copy);if(!reply)return '';return `A possible reply: Black’s ${names[reply.piece]} could move ${reply.from} → ${reply.to}${reply.captured?', capturing your '+names[reply.captured]:''}. This is a short look ahead, not a prediction.`;}
function render(){let legal=selected?game.moves({square:selected,verbose:true}):[];$('board').innerHTML='';
for(let r=8;r>=1;r--)for(let f=0;f<8;f++){let sq=String.fromCharCode(97+f)+r,p=game.get(sq),b=document.createElement('button');b.className='square'+((f+r)%2===0?' dark':'')+(selected===sq?' selected':'')+(showThreats&&p?.color==='w'&&game.isAttacked(sq,'b')?' threatened':'')+(hinted?.to===sq?' hint-square':'')+(guided&&legal.some(m=>m.to===sq)?' legal':'')+(pending?.to===sq?' preview':'')+(last&&(last.from===sq||last.to===sq)?' last':'');b.setAttribute('aria-label',`${sq}${p?' '+(p.color==='w'?'white':'black')+' '+names[p.type]:', empty'}${guided&&legal.some(m=>m.to===sq)?', legal move':''}${showThreats&&p?.color==='w'&&game.isAttacked(sq,'b')?', attacked by Black':''}`);b.onclick=()=>{selectSquare(sq);[...$('board').children].find(x=>x.dataset.square===sq)?.focus({preventScroll:true});};b.dataset.square=sq;b.onkeydown=e=>{let directions={ArrowLeft:-1,ArrowRight:1,ArrowUp:-8,ArrowDown:8};if(e.key in directions){e.preventDefault();let squares=[...$('board').children],i=squares.indexOf(b),n=i+directions[e.key];if(n>=0&&n<64)squares[n].focus();}};if(p)b.innerHTML=`<span class="piece ${p.color==='w'?'white':'black'}" aria-hidden="true">${symbols[p.type]}</span>`;if(f===0)b.innerHTML+=`<span class="coord">${r}</span>`;if(r===1)b.innerHTML+=`<span class="coord file">${String.fromCharCode(97+f)}</span>`;if(showThreats&&p?.color==='w'&&game.isAttacked(sq,'b'))b.innerHTML+='<span class="danger-mark" aria-hidden="true">!</span>';$('board').append(b);}
$('preview').hidden=!pending;$('promotion-label').hidden=!pending?.promotion;$('undo').disabled=!game.history().length;$('hint').disabled=busy||game.isGameOver()||solved;$('confirm').disabled=busy;
progress();$('hint').innerHTML='<span>✧ '+(hintLevel===0?'Give me a clue':hintLevel===1?'Show the piece':'Show the move')+'</span>';let status=solved?'Nicely done! Choose your next challenge.':busy?'Partner is thinking…':game.isCheckmate()?'Checkmate · '+(game.turn()==='b'?'You won!':'A new lesson learned'):game.isStalemate()?'Draw · stalemate':game.isThreefoldRepetition()?'Draw · repeated position':game.isInsufficientMaterial()?'Draw · insufficient material':game.isDraw()?'Draw · 50-move rule':game.isCheck()?'Your king is in check · find a safe response':'Your turn · choose a white piece';$('status').textContent=status; $('board-guide').textContent=busy?'Your partner is thinking. Look for what changed on the board.':solved?'✓ You did it! Continue when you’re ready.':game.isGameOver()?status:pending?'③ Read the move preview below, then choose Play this move.':selected?(guided?`② Choose a dotted square for your ${names[game.get(selected).type]}.`:`Choose a destination for your ${names[game.get(selected).type]}.`):mode==='lessons'?lessons[lesson].text:mode==='puzzles'?(puzzleStage?'Now finish the tactic: make your follow-up move.':puzzles[puzzle].text):guided?'① Pick any white piece. Dots show its legal moves.':'Pick a white piece and try choosing a move without the dots.'; $('next-step').hidden=!solved;$('next-step').textContent=mode==='lessons'?(lesson<lessons.length-1?'Next lesson →':'Put it into practice →'):'Next puzzle →'; $('review').hidden=!reviewText;$('review-copy').textContent=reviewText;
let hist=game.history({verbose:true});$('move-count').textContent=hist.length+' moves';$('history').innerHTML=hist.length?'':'<p class="empty">Your story starts with your first move.</p>';for(let i=hist.length-1;i>=0;i--){let m=hist[i];$('history').innerHTML+=`<div class="plain-move"><span>${m.color==='w'?'You':'Partner'}</span><div>${names[m.piece][0].toUpperCase()+names[m.piece].slice(1)} ${m.from} → ${m.to}${m.captured?' · captured '+names[m.captured]:''}${m.promotion?' · became '+names[m.promotion]:''}</div><small>${m.san}</small></div>`;}

}
function selectSquare(sq,forcePreview=false){if(busy||game.isGameOver()||solved)return;hinted=null;let p=game.get(sq);if(p?.color==='w'){selected=sq;pending=null;coach(`Meet your ${names[p.type]}.`,{p:'Pawns move straight forward and capture diagonally. On their first move, they can advance two squares.',n:'A knight moves in an L shape: two squares, then one to the side. It can jump over other pieces.',b:'A bishop moves any distance diagonally, until another piece blocks its path.',r:'A rook moves any distance along a row or column, until another piece blocks its path.',q:'The queen moves any distance along a row, column, or diagonal.',k:'The king moves one square in any direction, but can never move into an attack.'}[p.type]);render();return;}let m=selected&&game.moves({square:selected,verbose:true}).find(m=>m.to===sq);if(m){pending=m.promotion?{...m,promotion:'q'}:m;$('promotion').value='q';$('preview-text').textContent=explain(pending);$('reply-preview').textContent=mode==='play'?replyPreview(pending):'';if(!guided&&mode==='play'&&!pending.promotion&&!forcePreview){commit();return;}coach('See the move before you make it.','Read the idea below. You can play it, or pick another piece.');render();if(matchMedia('(max-width:700px)').matches)$('move-dock').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});}else{pending=null;selected=null;render();}}
function commit(){if(!pending||busy)return;let m={from:pending.from,to:pending.to,promotion:$('promotion').value};if(mode==='lessons'&&(m.from!==lessons[lesson].from||m.to!==lessons[lesson].to)){coach('A legal move. Try the lesson’s idea.',lessons[lesson].text);pending=null;selected=null;render();return;}let played=game.move(m);hintLevel=0;hinted=null;last=played;pending=null;selected=null;if(mode==='puzzles'){
  const challenge=puzzles[puzzle],target=puzzleStage?challenge.follow:challenge;
  const correct=challenge.mate?game.isCheckmate():m.from===target.from&&m.to===target.to&&(!target.promotion||m.promotion===target.promotion);
  if(!correct){let stalemate=game.isStalemate();game.undo();last=null;coach('Try a different idea.',stalemate?'That leaves the king without a move, but not in check: stalemate. Try again.':puzzleStage?'Look for the capture your first move made possible.':challenge.text+' Use a clue if you need one.');}
  else if(challenge.follow&&!puzzleStage){const reply=game.move(challenge.reply);last=reply;puzzleStage=1;coach('Good start. Now finish the idea.',`Black replied ${reply.san}. Your first move attacked two pieces. Capture the other target now.`);}
  else {solved=true;puzzlesCompleted.add(puzzle);saveProgress();activity();coach(challenge.mate?'Checkmate. You found it!':'You saw it through.',challenge.why);}
}else if(mode==='lessons'){solved=true;completed.add(lesson);saveProgress();activity();coach('That’s it. You’ve got the idea.',lessons[lesson].why);}else{coach('One move wiser.',explainAfter(played));if(!game.isGameOver()){busy=true;timer=setTimeout(()=>{let reply=bestMove(game);if(reply){game.move(reply);last=reply;const attacked=game.board().flat().filter(p=>p&&p.color==='w'&&game.isAttacked(p.square,'b')); reviewText=`You moved your ${names[played.piece]} from ${played.from} to ${played.to}. Black moved its ${names[reply.piece]} from ${reply.from} to ${reply.to}.${reply.captured?' Your '+names[reply.captured]+' was captured. Use Take back to explore another move.':''} ${attacked.length?'Look at your attacked '+attacked.map(p=>names[p.type]+' on '+p.square).join(', ')+'. Can you move, defend, or make a useful trade?':'None of your pieces is currently attacked. Look for a move that improves a piece or controls the center.'}`;coach(game.isCheck()?'Your king needs you.':'Your partner has replied.',`Black played ${reply.san}${reply.captured?', capturing your '+names[reply.captured]:''}. ${game.isCheck()?'Get out of check by moving the king, blocking the attack, or capturing the attacker.':'Before you move, ask: what is Black attacking, and is my king safe?'}`);}busy=false;endMessage();render();},450);}else endMessage();}render();}
function explainAfter(m){return `You played ${m.san}. Look at the squares your ${names[m.piece]} now controls. Your partner will reply next.`;}
function endMessage(){if(game.isCheckmate())coach(game.turn()==='b'?'Checkmate. Well played!':'Checkmate. Let’s learn from it.',game.turn()==='b'?'You left the opposing king with no legal escape. Start a fresh game to practice again.':'Use Take back to explore another response, or start a new game. Each attempt teaches you something.');else if(game.isDraw())coach('A shared result: a draw.','Neither player wins this game. The board status below tells you why. Start fresh to try again.');}
function start(nextMode=mode,resume=false){if(mode==='play'&&nextMode!=='play'){if(busy)game.undo();practiceSnapshot={pgn:game.pgn(),reviewText};}clearTimeout(timer);busy=false;mode=nextMode;selected=pending=last=null;solved=false;hintLevel=0;puzzleStage=0;hinted=null;reviewText='';game=new Chess(mode==='lessons'?lessons[lesson].fen:mode==='puzzles'?puzzles[puzzle].fen:undefined);if(resume&&mode==='play'&&practiceSnapshot){game.loadPgn(practiceSnapshot.pgn);reviewText=practiceSnapshot.reviewText;}document.querySelectorAll('[data-mode]').forEach(b=>{b.classList.toggle('active',b.dataset.mode===mode);b.setAttribute('aria-pressed',String(b.dataset.mode===mode));});$('opponent-label').innerHTML=mode==='play'?'Your practice partner<small>A patient opponent, at your pace</small>':mode==='lessons'?'A little lesson<small>One idea. One move. All yours.</small>':'Your puzzle board<small>White to move · '+puzzles[puzzle].theme+'</small>';if(mode==='play'&&game.history().length)coach('Welcome back to your game.','Your position is right where you left it. Look for checks, captures, and threats before choosing a move.');else if(mode==='play')coach('Let’s find your first move.','Click a white piece. The dots show where it can go. Try moving a center pawn to give your other pieces room to join in.');else coach(mode==='lessons'?lessons[lesson].name:puzzles[puzzle].name,mode==='lessons'?lessons[lesson].text:puzzles[puzzle].text);activity();render();}
function activity(){let el=$('activity');
if(mode==='play'){
const next=lessons.findIndex((_,i)=>!completed.has(i));
el.innerHTML=`<div class="card-label">YOUR LEARNING PATH</div><h3>${next<0?'Put your ideas into practice':lessons[next].name}</h3><p>${next<0?'You have explored every lesson. Try a puzzle to practice spotting the idea without step-by-step instructions.':'One useful idea, then a chance to try it on the board.'}</p><button class="primary" id="start-lesson">${next<0?'Practice a tactic':'Continue learning'} <span>→</span></button><div class="thinking-checklist"><b>Before every move</b><span>1. Is my king safe?</span><span>2. Are there checks or captures?</span><span>3. What is my opponent threatening?</span></div>`;
$('start-lesson').onclick=()=>{if(next<0)start('puzzles');else{lesson=next;start('lessons');}};
}else if(mode==='lessons'){
let chapter='';el.innerHTML='<div class="card-label">YOUR CURRICULUM · '+completed.size+' / '+lessons.length+'</div>'+lessons.map((l,i)=>{let heading=l.chapter!==chapter?`<h3 class="chapter">${l.chapter}</h3>`:'';chapter=l.chapter;return heading+`<button class="lesson-row ${lesson===i?'active':''}" data-lesson="${i}"><span>${l.piece}</span>${l.name}<span>${completed.has(i)?'✓':String(i+1).padStart(2,'0')}</span></button>`;}).join('');
el.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>{lesson=+b.dataset.lesson;start();});
}else{
el.innerHTML='<div class="card-label">TACTICS TO RECOGNIZE · '+puzzlesCompleted.size+' / '+puzzles.length+'</div><p>Look for the idea first. Ask for a clue whenever you need one.</p><div class="puzzle-list">'+puzzles.map((p,i)=>`<button data-puzzle="${i}" class="puzzle-card ${puzzle===i?'active':''}"><span>${puzzlesCompleted.has(i)?'✓':String(i+1).padStart(2,'0')}</span><div>${p.name}<small>${p.theme}</small></div></button>`).join('')+'</div>';
el.querySelectorAll('[data-puzzle]').forEach(b=>b.onclick=()=>{puzzle=+b.dataset.puzzle;start();});}}
$('confirm').onclick=commit;$('cancel').onclick=()=>{pending=null;selected=null;render();};$('promotion').onchange=()=>{if(pending){pending={...pending,promotion:$('promotion').value};$('preview-text').textContent=explain(pending);$('reply-preview').textContent=mode==='play'?replyPreview(pending):'';}};
$('undo').onclick=()=>{if(mode==='puzzles'){start();return;}clearTimeout(timer);busy=false;if(game.history().length){game.undo();if(mode==='play'&&game.turn()==='b')game.undo();}solved=false;reviewText='';hinted=null;selected=pending=last=null;coach('A fresh look at the same moment.','Nothing lost. Try a different move and see how the position changes.');render();};$('restart').onclick=()=>start();$('hint').onclick=()=>{
if(busy||solved||game.isGameOver())return;
hintLevel=Math.min(hintLevel+1,3);pending=null;
let target,clue;
if(mode==='lessons'){target=lessons[lesson];clue=lessons[lesson].text;}
else if(mode==='puzzles'){const challenge=puzzles[puzzle];target=puzzleStage?challenge.follow:challenge;clue=puzzleStage?'Your first move created a second target. Look for the capture.':challenge.hints[hintLevel-1];}
else{target=bestMove(game);clue=game.isCheck()?'Your king is in check. Consider moving it, blocking, or capturing the attacker.':'Look for checks, useful captures, and pieces you can bring toward the center.';}
if(!target)return;
selected=hintLevel>=2?target.from:null;hinted=hintLevel===3?target:null;
coach(hintLevel===1?'A clue, not the answer.':hintLevel===2?'Look at this piece.':`Try ${target.from} → ${target.to}.`,hintLevel===3?(mode==='play'?explain(target):clue):hintLevel===2?`Look at your ${names[game.get(target.from).type]} on ${target.from}. ${clue}`:clue);
render();};document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{if(b.dataset.mode!==mode)start(b.dataset.mode,true);});$('help').onclick=()=>$('help-dialog').showModal();$('close-help').onclick=$('begin').onclick=()=>$('help-dialog').close();
$('learning-style').onchange=e=>{guided=e.target.value==='guided';showThreats=guided;$('show-threats').checked=showThreats;pending=null;selected=null;hinted=null;coach(guided?'Your guide is beside you.':'Try trusting your own judgment.',guided?'Legal dots, threat warnings, and move previews are on.':'Legal dots and automatic move previews are off for practice games. Hints and Take back are always available.');render();};
$('show-threats').onchange=e=>{showThreats=e.target.checked;render();};$('next-step').onclick=()=>{if(mode==='lessons'){if(lesson<lessons.length-1){lesson++;start();}else start('play',true);}else {puzzle=(puzzle+1)%puzzles.length;start();}};
start();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_chess_position',description:'Read the current board and legal moves.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({fen:game.fen(),mode,legalMoves:game.moves(),busy,puzzleStage,solved,lessonsCompleted:completed.size,puzzlesCompleted:puzzlesCompleted.size})},{name:'preview_chess_move',description:'Stage a legal white move for the learner to review and confirm. Does not play the move.',inputSchema:{type:'object',properties:{from:{type:'string'},to:{type:'string'}},required:['from','to'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(busy||solved||game.turn()!=='w'||!game.moves({verbose:true}).some(m=>m.from===input.from&&m.to===input.to))throw new Error('Move is not available.');selectSquare(input.from);selectSquare(input.to,true);return {staged:!!pending,from:pending?.from,to:pending?.to};}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{});}catch{}}}

mountExplorer(document,()=>game.fen());
